import { useCallback, useMemo } from 'react';
import { useIntl } from 'react-intl';

import { NoDataYet } from 'components';
import { featureToggles } from 'config/featureToggle';
import { useGlobalDataAvailability } from 'contexts';
import {
  useFeatureToggle,
  useMediaQuery,
  usePageFilterApplied,
  useRelatedAnalysisNavigation,
  useSubFilters,
} from 'hooks';
import { useBffData } from 'hooks/useBffData';
import { AISummary } from 'pages/components/AISummary';
import {
  buildRelatedAnalysisCardProps,
  RelatedAnalysisCard,
} from 'pages/components/RelatedAnalysisCard';
import { BRAND_POWER_BOOK_OVERVIEW_PATH } from 'pages/pillars/PortfolioBrand/BrandPowerBook/constants';

import { powerWaterfallConfig } from '../../../config';
import { PERFORMANCE_TOOL_PAGE_NAME } from '../../../constants';
import {
  usePerformanceToolData,
  usePerformanceToolDrillDownAiSummary,
} from '../../../hooks';
import { StyledPerformanceToolContent } from '../../../PerformanceTool.styles';
import { PerformanceSection } from '../../Sections';

interface PowerProps {
  onFilterChange: (key: string, value: string) => void;
}

const PERIOD_VALUES = ['YTD', 'QTD'] as const;

export const Power: React.FC<PowerProps> = ({ onFilterChange }: PowerProps) => {
  const { formatMessage } = useIntl();
  const isLargeScreen = useMediaQuery('(min-width: 1440px)');
  const { applied } = usePageFilterApplied(PERFORMANCE_TOOL_PAGE_NAME);
  const { shouldShowGlobalBanner } = useGlobalDataAvailability();
  const isGlobalView = applied.country === 'ABI';
  const showEmptyState = shouldShowGlobalBanner('power') && isGlobalView;
  const { activeSubFilters } = useSubFilters();
  const { aiSummaryEntry, aiSummaryFilters, isAiSummaryEnabled } =
    usePerformanceToolDrillDownAiSummary('brand-power', applied);

  const bigNumbersBffData = useBffData({
    id: 'value-creation_performance-tool_drill-down_brand-power_overtime-performance',
    kpiGroup: 'power',
    subFilters: {
      page_filter: applied.portfolios ?? 'All',
      timeframe: 'YTD',
      kpi: applied.kpis,
    },
    skipMainFilters: false,
    skipRequest: false,
  });

  const overtimeBffData = useBffData({
    id: 'value-creation_performance-tool_drill-down_brand-power_overtime-trends',
    kpiGroup: 'power',
    subFilters: {
      page_filter: applied.portfolios ?? 'All',
      timeframe: applied.periods,
      kpi: applied.kpis,
    },
    skipMainFilters: false,
    skipRequest: false,
  });

  const waterfallBffData = useBffData({
    id: 'value-creation_performance-tool_drill-down_brand-power_contribution',
    kpiGroup: 'power',
    subFilters: {
      page_filter: applied.portfolios ?? 'All',
      timeframe: applied.periods,
      waterfall_filter: activeSubFilters?.waterfall_view_by,
      kpi: applied.kpis,
    },
    skipMainFilters: false,
    skipRequest: false,
  });

  const bigNumbersData = usePerformanceToolData(
    ['overtime-performance'],
    bigNumbersBffData,
  );

  const overtimeData = usePerformanceToolData(
    ['overtime-trends'],
    overtimeBffData,
  );

  const waterfallData = usePerformanceToolData(
    ['contribution'],
    waterfallBffData,
  );

  const waterfallVariant = useMemo(
    () => (isLargeScreen ? 'large' : 'small'),
    [isLargeScreen],
  );

  const selectedBigNumberIndex = useMemo(() => {
    const index = PERIOD_VALUES.indexOf(
      applied.periods as (typeof PERIOD_VALUES)[number],
    );
    return Math.max(index, 0);
  }, [applied.periods]);

  const handleBigNumbersSelect = useCallback(
    (index: number) => {
      const selectedBigNumber = bigNumbersData['overtime-performance']?.[index];

      if (selectedBigNumber) {
        onFilterChange('periods', PERIOD_VALUES[index]);
      }
    },
    [onFilterChange, bigNumbersData],
  );

  const showDrivers = useMemo(() => {
    return !!applied.brands && applied.brands !== 'All';
  }, [applied]);
  const [isRelatedAnalysisEnabled] = useFeatureToggle(
    featureToggles.pillar.portfolioBrand.submenus.brandPowerBook
      .relatedAnalysisCard,
  );
  const { navigateToRelatedAnalysis } = useRelatedAnalysisNavigation({
    sourcePageName: PERFORMANCE_TOOL_PAGE_NAME,
    destinationPath: BRAND_POWER_BOOK_OVERVIEW_PATH,
    origin: 'performance-tool',
  });

  const relatedAnalysisProps = buildRelatedAnalysisCardProps({
    formatMessage,
    messages: {
      title: 'ValueCreation.PerformanceTool.relatedAnalysis.title',
      description: 'ValueCreation.PerformanceTool.relatedAnalysis.description',
      buttonLabel: 'ValueCreation.PerformanceTool.relatedAnalysis.buttonLabel',
      warning: 'ValueCreation.PerformanceTool.relatedAnalysis.warning',
    },
  });

  if (showEmptyState) {
    return (
      <StyledPerformanceToolContent $centered>
        <NoDataYet
          dataTestId="power-global-unavailable"
          title={formatMessage({ id: 'GlobalData.bannerTitle' })}
          description={formatMessage({ id: 'GlobalData.bannerMessage' })}
          illustration="noDataAvailable"
        />
      </StyledPerformanceToolContent>
    );
  }

  return (
    <StyledPerformanceToolContent>
      {isAiSummaryEnabled && aiSummaryEntry && (
        <AISummary
          pageName={PERFORMANCE_TOOL_PAGE_NAME}
          kpiGroup="power"
          summaryPageIdentifier={aiSummaryEntry.summaryPageIdentifier}
          subFilters={aiSummaryFilters}
          dataTestId="performance-tool-drilldown-ai-summary-brand-power"
        />
      )}

      <PerformanceSection
        measure="[ % ]"
        bigNumbersProps={{
          title: 'Overtime Performance',
          data: bigNumbersData['overtime-performance'] ?? undefined,
          loading: bigNumbersBffData.loading,
          error: bigNumbersBffData.error,
          onSelect: handleBigNumbersSelect,
          defaultSelected: selectedBigNumberIndex,
        }}
        lineBarChartsData={overtimeData['overtime-trends'] ?? undefined}
        waterfallData={waterfallData['contribution'] ?? undefined}
        waterfallRequest={waterfallBffData}
        lineBarChartsRequest={overtimeBffData}
        waterfallVariant={waterfallVariant}
        showDrivers={showDrivers}
        waterfallConfig={powerWaterfallConfig}
      />
      {isRelatedAnalysisEnabled && (
        <RelatedAnalysisCard
          {...relatedAnalysisProps}
          onNavigate={navigateToRelatedAnalysis}
          dataTestId="performance-tool-related-analysis-power"
        />
      )}
    </StyledPerformanceToolContent>
  );
};
